            aWandererB = aWandererB ^ (((RotL64(aIngress, 13U) + aOrbiterE) + RotL64(aOrbiterC, 51U)) + aWUSaltF[((aIndex + 306U)) & S_SALT1]);
            aWandererG = aWandererG + (((RotL64(aScatter, 27U) + aOrbiterD) + RotL64(aOrbiterE, 24U)) + aWUSaltE[(((511U - aIndex) + 183U)) & S_SALT1]);
            //
            aCarry = aCarry + (RotL64(aWandererE, 28U) ^ aWandererH);
