            aOrbiterE = (((aWandererJ + RotL64(aIngress, 19U)) + RotL64(aCarry, 41U)) + 0x4A8389B70B9D6B92ULL) + aOASaltH[((aIndex + 429U)) & S_SALT1];
            aOrbiterC = ((aWandererE + RotL64(aScatter, 3U)) + 0xEE91DEDE3AAD0287ULL) + aOASaltG[((aIndex + 240U)) & S_SALT1];
