            aOrbiterF = (((aWandererI + RotL64(aPrevious, 56U)) + RotL64(aCarry, 21U)) + 0x255B897E8670FAC8ULL) + aOASaltG[(((511U - aIndex) + 257U)) & S_SALT1];
